CREATE TABLE products(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,sku VARCHAR(64) NOT NULL UNIQUE,name VARCHAR(200) NOT NULL,category_id BIGINT UNSIGNED NOT NULL,base_unit VARCHAR(50) NOT NULL,packaging VARCHAR(250) NOT NULL DEFAULT '',cost_price DECIMAL(19,4) NULL,image_key VARCHAR(36) NULL,status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE',version BIGINT NOT NULL DEFAULT 1,FOREIGN KEY(category_id) REFERENCES categories(id),CHECK(cost_price IS NULL OR cost_price>=0),CHECK(status IN ('ACTIVE','DISCONTINUED')));
CREATE TABLE product_transaction_references(product_id BIGINT UNSIGNED NOT NULL,reference_type VARCHAR(40) NOT NULL,reference_id VARCHAR(100) NOT NULL,PRIMARY KEY(product_id,reference_type,reference_id),FOREIGN KEY(product_id) REFERENCES products(id));
